import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or x.shape[0] != 5:
        raise ValueError("Input must be a 1D array of shape (5,).")

    fitness = 0.3 * np.log1p(np.sum(x**2)) + 0.1 * np.sum(x) + 0.2 * np.sum(np.sin(x**2))

    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or x.shape[0] != 5:
        raise ValueError("Input must be a 1D array of shape (5,).")

    fitness = 0.3 * np.log1p(np.sum(x**2)) + 0.1 * np.sum(x)

    # Introduce more non-linearity and interactions
    fitness += 0.2 * np.sum(np.sin(x**2) * (0.1*x**3 + 0.05))

    # Add pairwise interaction with a quartic term.
    for i in range(5):
        for j in range(i + 1, 5):
            fitness += 0.01 * (x[i]**2 * x[j]**2)

    return float(fitness)

import numpy as np

def problem(x: np.ndarray) -> float:
    x_scaled = (x + 5) / 10
    sphere_term = np.sum(x_scaled**2)
    exp_modulation = np.exp(-5 * (x_scaled[0] - 0.5)**2)
    return float(exp_modulation * sphere_term)

