import numpy as np

def problem(x: np.ndarray) -> float:
    sphere_term = np.sum(x**2)
    exp_modulation = np.exp(-(x[0] - 1)**2)
    return float(exp_modulation * sphere_term * 0.01)

import numpy as np

def problem(x: np.ndarray) -> float:
    x_scaled = (x + 5) / 10
    sphere_term = np.sum(x_scaled**2)
    exp_modulation = np.exp(-5 * (x_scaled[0] - 0.5)**2)
