import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or len(x) != 5:
        raise ValueError("Input must be a 1D array of dimension 5.")

    sphere_term = np.sum(x**2)
    sine_modulation = np.sin(x[0])
    tanh_modulation = np.tanh(x[1])
    result = sphere_term * (1 + 0.5 * sine_modulation + 0.2 * tanh_modulation)

    return float(result)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or len(x) != 5:
        raise ValueError("Input must be a 5D array.")
    x_scaled = (x + 5) / 10
    sphere_term = np.sum(x_scaled**2)
    exp_modulation = np.exp(-5 * (x_scaled[0] - 0.25)**2)
    skew_term = 0.5 * (x_scaled[0] - 0.5)**3
    sigmoid_scale = 1 / (1 + np.exp(-20 * (np.std(x_scaled) - 0.2)))
    interaction_term = 1.0
    for i in range(len(x_scaled)):
        for j in range(i + 1, len(x_scaled)):
            interaction_term *= np.sin(np.pi * x_scaled[i]) * np.sin(np.pi * x_scaled[j])
    return float(sigmoid_scale * (exp_modulation * sphere_term + skew_term) * interaction_term)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or len(x) != 5:
        raise ValueError("Input must be a 5D array.")

    sphere_term = np.sum(x**2)
    gaussian_modulation = np.exp(-x[0]**2)
    skew_term = 0.1 * x[0]**3
    sigmoid_scale = 1 / (1 + np.exp(-np.mean(x)))

    return float(sigmoid_scale * (gaussian_modulation * sphere_term + skew_term))

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.ndim != 1 or len(x) != 5:
        raise ValueError("Input must be a 5D array.")
    x_scaled = (x + 5) / 10
    sphere_term = np.sum(x_scaled**2)
    gaussian_modulation = np.exp(-5 * (x_scaled[0] - 0.25)**2)
    sigmoid_scale = 1 / (1 + np.exp(-20 * ((x_scaled[0] + x_scaled[1]) / 2 - 0.5)))
    return float(sigmoid_scale * gaussian_modulation * sphere_term)
